@Command([EditDocument]; "1");

@If(ProName="";@Return(@Do(@Command([EditGotoField];"ProName");@Prompt([Ok];"Missing Value";"Please enter Project/ Job Name before proceeding!")));"");
@If(ComDate="";@Return(@Do(@Command([EditGotoField];"ComDate");@Prompt([Ok];"Missing Value";"Please enter Commencement Date before proceeding!")));"");
@If(ExpDate="";@Return(@Do(@Command([EditGotoField];"ExpDate");@Prompt([Ok];"Missing Value";"Please enter Expected Completion Date before proceeding!")));"");
@If(JobLocation="";@Return(@Do(@Command([EditGotoField];"JobLocation");@Prompt([Ok];"Missing Value";"Please enter Job Location before proceeding!")));"");
@If(JobType="";@Return(@Do(@Command([EditGotoField];"JobType");@Prompt([Ok];"Missing Value";"Please enter Job Type before proceeding!")));"");
@If(CompName="";@Return(@Do(@Command([EditGotoField];"CompName");@Prompt([Ok];"Missing Value";"Please enter Company Name before proceeding!")));"");
@If(PICContact="";@Return(@Do(@Command([EditGotoField];"PICContact");@Prompt([Ok];"Missing Value";"Please enter PIC Contact Name before proceeding!")));"");
@If(CIDBRegister="";@Return(@Do(@Command([EditGotoField];"CIDBRegister");@Prompt([Ok];"Missing Value";"Please enter CIDB Registration No. before proceeding!")));"");
@If(ContactNo="";@Return(@Do(@Command([EditGotoField];"ContactNo");@Prompt([Ok];"Missing Value";"Please enter Contact No before proceeding!")));"");

FIELD CA					:="Submitted";
FIELD HRName	  	:=@V3UserName;
FIELD HRDate			:=@Now;

@Command([FileSave]);

@MailSend(SHE;CCMails:DocAuthor;NULL;@DbTitle + " : Verified By HR." ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

